import{_ as a,C as i,c as d,o as l,a3 as n,G as s,j as t,a as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Work order dependencies","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/advanced-configuration/work-order-dependencies.md","filePath":"master/supply-chain/manufacturing/advanced-configuration/work-order-dependencies.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/manufacturing/advanced-configuration/work-order-dependencies.md"};function p(g,e,u,h,m,f){const r=i("ImagePopup");return l(),d("div",null,[e[0]||(e[0]=n('<h1 id="work-order-dependencies" tabindex="-1">Work order dependencies <a class="header-anchor" href="#work-order-dependencies" aria-label="Permalink to &quot;Work order dependencies&quot;">​</a></h1><p>A dependency says that one step cannot start until another step is finished. This keeps the shop floor in the right order. For the sample laptop, <strong>Test &amp; Pack</strong> must wait until <strong>Assemble Components</strong> is done.</p><blockquote><p><strong>In simple words:</strong> Dependencies decide which work order goes first.</p></blockquote><p>Open <code>Manufacturing → Settings → Manage Operations</code>, then <code>Manufacturing → Products → Bills of Materials</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Gate</p><p>In <code>Manufacturing → Settings → Manage Operations</code>, turn on <strong>Work Order Dependencies</strong>. It also turns on <strong>Work Orders</strong>. Turning <strong>Work Orders</strong> off turns it off again.</p></div>',6)),s(r,{src:"/images1/manufacturing/dep_settings.png",alt:"Manage Operations settings page with Work Orders and Work Order Dependencies both on"}),e[1]||(e[1]=n('<h2 id="default-behaviour-one-after-another" tabindex="-1">Default behaviour: one after another <a class="header-anchor" href="#default-behaviour-one-after-another" aria-label="Permalink to &quot;Default behaviour: one after another&quot;">​</a></h2><p>Aureus orders the work for you. Each work order waits for the one before it in the <strong>Operations</strong> list of the BoM. Steps run strictly in sequence.</p><p>Scenario: <strong>BOM-MC-LAPTOP</strong> has two operations, <strong>Assemble Components</strong> and <strong>Test &amp; Pack</strong>. <strong>Test &amp; Pack</strong> must wait for <strong>Assemble Components</strong>.</p><ol><li>Create a manufacturing order for <strong>Business Laptop</strong> with <strong>BOM-MC-LAPTOP</strong> and confirm it.</li><li>Open its <strong>Work Orders</strong> tab.</li></ol>',4)),s(r,{src:"/images1/manufacturing/dep_mo_work_orders.png",alt:"MO Work Orders tab with Assemble Components and Test & Pack, Test & Pack status Waiting for another work order"}),e[2]||(e[2]=t("ol",{start:"3"},[t("li",null,[o("Open the "),t("strong",null,"Test & Pack"),o(" work order. Its "),t("strong",null,"Blocked By"),o(" tab lists "),t("strong",null,"Assemble Components"),o(".")])],-1)),s(r,{src:"/images1/manufacturing/dep_wo_blocked_by.png",alt:"Work order view for Test & Pack, Blocked By tab showing the Assemble Components work order"}),e[3]||(e[3]=n('<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assemble Components  -&gt;  Finished  -&gt;  Test &amp; Pack becomes ready to start</span></span></code></pre></div><p>While the blocker is open, <strong>Test &amp; Pack</strong> shows <strong>Waiting for another work order</strong>. When <strong>Assemble Components</strong> is <strong>Finished</strong> (or cancelled), Aureus rechecks the next one. It moves to <strong>Ready</strong> once its components are available, or <strong>Waiting for components</strong> if they are not.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Blockers are created with the work orders. Plan the order of your operations before you confirm the manufacturing order.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./operations.html">Operations</a></li><li><a href="./../workflows/work-orders.html">Work orders</a></li><li><a href="./../workflows/plan-and-schedule.html">Plan and schedule</a></li><li><a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a></li></ul>',5))])}const b=a(c,[["render",p]]);export{_ as __pageData,b as default};
